import {translate as t,locale} from './i18n.js';
const $=id=>document.getElementById(id);
function node(tag,text){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;return el;}
function publicUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}}
const search=$('resource-search');if(search)search.addEventListener('input',()=>{let count=0;for(const card of document.querySelectorAll('[data-resource]')){card.hidden=!card.textContent.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase());if(!card.hidden)count++;}$('resources-empty').hidden=count>0;});
const form=$('friend-apply-form');
if(form){
 const dialog=$('friend-application'),button=$('friend-apply-submit');let configured=false,busy=false;
 const message=(key)=>{$('friend-apply-status').textContent=t(key);};
 $('friend-apply-open').addEventListener('click',()=>{dialog.showModal();if(!configured)message('Applications are not open yet. The owner needs to connect the private review database.');});$('friend-apply-close').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('cancel',event=>{if(busy)event.preventDefault();});
 fetch('/api/community/config',{credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(10000)}).then(r=>r.ok?r.json():{configured:false}).then(data=>{configured=data.configured===true;button.disabled=!configured;$('friend-availability').textContent=configured?'':t('Applications are not open yet. The owner needs to connect the private review database.');}).catch(()=>{$('friend-availability').textContent=t('Applications are not open yet. The owner needs to connect the private review database.');});
 form.addEventListener('submit',async event=>{event.preventDefault();if(!configured||busy||!form.reportValidity())return;const fields=new FormData(form);const value=Object.fromEntries(fields);value.consent=fields.has('consent');value.locale=locale;busy=true;button.disabled=true;message('Sending application…');try{const r=await fetch('/api/community/apply',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json'},body:JSON.stringify(value),signal:AbortSignal.timeout(15000)});if(!r.ok){message(r.status===409?'This site was already submitted, or the queue is full.':r.status===429?'Too many requests. Please wait one minute.':r.status===400?'Please check the fields and try again.':'The service is unavailable. Your form has not been cleared.');return;}const receipt=await r.json();if(receipt.submitted!==true)throw Error();message('Application received. It stays private until the owner approves it.');form.reset();}catch{message('The service is unavailable. Your form has not been cleared.');}finally{busy=false;button.disabled=!configured;}});
 fetch('/api/community/approved',{credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(10000)}).then(r=>r.ok?r.json():{friends:[]}).then(data=>{for(const item of (data.friends||[]).slice(0,100)){const url=publicUrl(item.url);if(!url||typeof item.name!=='string'||typeof item.description?.[locale]!=='string')continue;const card=node('article');card.className='resource-card';const img=node('img');img.src='/assets/companions/blank-cat.png';img.width=64;img.height=64;img.alt='';img.loading='lazy';const link=node('a',t('Visit website'));link.className='text-link';link.href=url;link.target='_blank';link.rel='noopener noreferrer nofollow';card.append(img,node('h2',item.name),node('p',item.description[locale]),link);$('approved-friends').append(card);}$('approved-community').hidden=!$('approved-friends').children.length;document.documentElement.dataset.communityReady='true';}).catch(()=>{document.documentElement.dataset.communityReady='true';});
}
